function loadProgress() {
	if (typeof window === "undefined") return defaultProgress();
	try {
		let raw = window.localStorage.getItem(KEY);
		if (!raw && typeof window.AndroidBridge?.loadProgress === "function") raw = window.AndroidBridge.loadProgress();
		if (!raw) return defaultProgress();
		return {
			...defaultProgress(),
			...JSON.parse(raw)
		};
	} catch {
		return defaultProgress();
	}
}
function saveProgress(p) {
	if (typeof window === "undefined") return;
	const serialized = JSON.stringify(p);
	try {
		window.localStorage.setItem(KEY, serialized);
	} catch {}
	try {
		if (typeof window.AndroidBridge?.saveProgress === "function") window.AndroidBridge.saveProgress(serialized);
	} catch {}
	window.dispatchEvent(new CustomEvent("cop-adam-progress"));
}
